local ok=require('ok');local json=require('ok.json');local hash=require('ok.hash');local root=ok.root:gsub('\\','/'):gsub('%s+$','');local out=root..'/output/street-social-city-production/traffic-v1'
local function raw(p)local f=assert(io.open(p,'rb'));local s=f:read('*a');f:close();return s end
local function read(p)return json.decode(raw(p))end
local function write(p,v)local f=assert(io.open(p,'wb'));f:write(type(v)=='string' and v or json.encode(v));f:close()end
local function esc(s)return tostring(s):gsub('&','&amp;'):gsub('<','&lt;'):gsub('>','&gt;'):gsub('"','&quot;')end
local install=read(out..'/install.json');local audit=read(out..'/audit.json');local campus=read(out..'/campus-audit.json');local capture=read(out..'/captures.json');local visual=read(out..'/visual-review.json');local package=read(root..'/output/street-social-city-production/day-night-v1/package.json');local layout=read(out..'/layout.json');local plan=read(out..'/plan.json')
local bridge=read(out..'/bridge-audit.json');local phase=read(out..'/signal-cycle-check.json');assert(bridge.status=='passed' and bridge.map_sha256==install.map_sha256 and #bridge.walkway_sweeps==6 and phase.status=='passed' and phase.samples==640 and phase.layout_sha256==hash.sha256_file(out..'/layout.json'));assert(install.lane_detail_planned==6229 and install.lane_detail_parts>6000 and install.bridge_lights>0)
